import java.util.*;

public class Solution {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { this.val = v; }
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNext()) return;
        List<String> tokens = new ArrayList<>();
        while (sc.hasNext()) tokens.add(sc.next());
        if (tokens.isEmpty() || tokens.get(0).equals("-1")) return;
        TreeNode root = new TreeNode(Integer.parseInt(tokens.get(0)));
        Queue<TreeNode> q = new LinkedList<>();
        q.add(root);
        int idx = 1;
        while (!q.isEmpty() && idx < tokens.size()) {
            TreeNode curr = q.poll();
            if (idx < tokens.size() && !tokens.get(idx).equals("-1")) {
                curr.left = new TreeNode(Integer.parseInt(tokens.get(idx)));
                q.add(curr.left);
            }
            idx++;
            if (idx < tokens.size() && !tokens.get(idx).equals("-1")) {
                curr.right = new TreeNode(Integer.parseInt(tokens.get(idx)));
                q.add(curr.right);
            }
            idx++;
        }
        Queue<TreeNode> levelQ = new LinkedList<>();
        levelQ.add(root);
        while (!levelQ.isEmpty()) {
            int size = levelQ.size();
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < size; i++) {
                TreeNode node = levelQ.poll();
                sb.append(node.val).append(i == size - 1 ? "" : " ");
                if (node.left != null) levelQ.add(node.left);
                if (node.right != null) levelQ.add(node.right);
            }
            System.out.println(sb.toString());
        }
    }
}

