#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode *left, *right;
} TreeNode;

TreeNode* createNode(int v) {
    TreeNode *n = (TreeNode*)malloc(sizeof(TreeNode));
    n->val = v; n->left = n->right = NULL;
    return n;
}

int main() {
    char token[32];
    if (scanf("%s", token) != 1) return 0;
    if (strcmp(token, "-1") == 0) return 0;
    TreeNode *root = createNode(atoi(token));
    TreeNode *q[20000];
    int head = 0, tail = 0;
    q[tail++] = root;
    while (head < tail) {
        TreeNode *curr = q[head++];
        if (scanf("%s", token) == 1) {
            if (strcmp(token, "-1") != 0) {
                curr->left = createNode(atoi(token));
                q[tail++] = curr->left;
            }
        } else break;
        if (scanf("%s", token) == 1) {
            if (strcmp(token, "-1") != 0) {
                curr->right = createNode(atoi(token));
                q[tail++] = curr->right;
            }
        } else break;
    }
    TreeNode *levelQ[20000];
    int lHead = 0, lTail = 0;
    levelQ[lTail++] = root;
    while (lHead < lTail) {
        int size = lTail - lHead;
        for (int i = 0; i < size; i++) {
            TreeNode *node = levelQ[lHead++];
            printf("%d%s", node->val, (i == size - 1) ? "\n" : " ");
            if (node->left) levelQ[lTail++] = node->left;
            if (node->right) levelQ[lTail++] = node->right;
        }
    }
    return 0;
}
